INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('ed7bc43e-cea9-4e76-8036-b9971b3ec03f', $g168b$compliance-matrix-primer$g168b$, 'guide', 1, 'draft', $g168b$Build the Compliance Matrix Before You Write a Word$g168b$, $g168b$[{"body":"<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">Build the Compliance Matrix Before You Write a Word</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Knowing that a missing item gets you screened out is not the same as having a way to make sure nothing is missing. A mid-sized solicitation imposes well over a hundred separate obligations, scattered across the announcement, the instructions to offerors, the evaluation criteria, and whatever component-specific document the announcement points at. No one holds that in their head, and no one finds them all by re-reading at the end.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The compliance matrix is the artifact that solves it, and it costs an afternoon.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">What a compliance matrix is</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A compliance matrix is a single table with one row for <strong>every requirement the solicitation imposes on you</strong>, and columns that answer: where is it addressed, who owns it, and is it done. Nothing more clever than that. Its power is that it converts a 60-page solicitation into a finite, checkable list.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A row typically records:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">The requirement, quoted, not paraphrased.</li><li style=\"margin:.25rem 0\">Where it comes from — the section and page of the solicitation.</li><li style=\"margin:.25rem 0\">Where you answer it — your volume, section and page.</li><li style=\"margin:.25rem 0\">Owner — one named person.</li><li style=\"margin:.25rem 0\">Status — not started, drafted, reviewed, done.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Finding the requirements</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Read the solicitation with a highlighter and pull every sentence containing:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">shall, must, is required to, will provide — hard requirements.</li><li style=\"margin:.25rem 0\">should, may — softer, but frequently scored anyway.</li><li style=\"margin:.25rem 0\">Anything in the instructions to offerors section, which is where format and submission rules hide.</li><li style=\"margin:.25rem 0\">Anything in the evaluation criteria, which tells you what reviewers actually score.</li></ul>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Two rules that save proposals. First, quote the requirement <strong>verbatim</strong> — a paraphrase silently drops the qualifier that mattered. Second, split compound requirements: &quot;the offeror shall describe the approach and provide a schedule and identify key personnel&quot; is <strong>three</strong> rows, not one, because it is three ways to be incomplete.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Requirements are not only in the narrative</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The rows that get missed are rarely technical. They are the administrative ones: a letter of support, a current SAM registration, a signed certification, a data-management plan, a specific file naming convention, a page-limited summary, a form nobody read past the title of. Every one of those is a row.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Working the matrix</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Build it <strong>before</strong> you start writing, not after. Used properly it is the proposal outline — you write to the rows, and the volume structure falls out of it. Review it at every checkpoint: an item that is still unowned two days before the deadline is the item that will be missing.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The last pass before submission is a straight read of the matrix, row by row, against the assembled document. Not from memory. Against the document.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The matrix is not something you build by hand here. When an opportunity is curated, the compliance side captures the solicitation's requirements, and a matrix is instantiated with your proposal the moment it is provisioned — every required item already a row, tied to the volume and section that answers it.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">From there it stays current on its own: locking a section advances the items it satisfies, and submission readiness reads the matrix directly, so the verdict on the overview page is the state of your requirements, not somebody's recollection of it. If the agency amends the solicitation, the change is detected, confirmed, and fanned out to every affected build with an acknowledgement — so a requirement that appeared after you started writing does not quietly stay missing.</p>","title":"Build the Compliance Matrix Before You Write a Word","excerpt":"A solicitation can carry two hundred requirements. The matrix is the one artifact that keeps a team from losing one — and it doubles as your proposal outline.","section":"body","metadata":{}}]$g168b$::jsonb, $g168b${"tags":["compliance","proposal management","shall statements","getting started"],"author":null,"canvas":{"nodes":[],"canvas":{"width":612,"footer":null,"format":"custom","header":null,"height":792,"margins":{"top":72,"left":72,"right":72,"bottom":72},"max_pages":null,"max_slides":null,"font_default":{"size":12,"family":"Times New Roman"},"line_spacing":1.15},"version":2,"metadata":{"title":"Build the Compliance Matrix Before You Write a Word","status":"in_progress","volume_id":"","created_at":"","proposal_id":"","version_number":1,"solicitation_id":"","last_modified_at":"","last_modified_by":"","required_item_id":""},"sections":[{"id":"31742d66-626a-406d-8243-42b2859dd932","title":"Build the Compliance Matrix Before You Write a Word","groups":[{"id":"7ecf57fa-dc5f-4ac2-b2b3-e0b6f20ca9d6","nodes":[{"id":"8ef8c512-97a1-4264-91e0-9f788596c84d","type":"heading","style":{},"content":{"text":"Build the Compliance Matrix Before You Write a Word","level":1},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"4c7c79e3-3f23-4ddf-842c-816ae5a7f959","type":"text_block","style":{},"content":{"text":"Knowing that a missing item gets you screened out is not the same as having a way to make sure nothing is missing. A mid-sized solicitation imposes well over a hundred separate obligations, scattered across the announcement, the instructions to offerors, the evaluation criteria, and whatever component-specific document the announcement points at. No one holds that in their head, and no one finds them all by re-reading at the end."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"42b534b8-a937-4e12-97b2-bfc68fac6498","type":"text_block","style":{},"content":{"text":"The compliance matrix is the artifact that solves it, and it costs an afternoon."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"c66a1dde-d2d4-4f14-848a-539708cb34ea","type":"heading","style":{},"content":{"text":"What a compliance matrix is","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"c8a7a9e4-eedf-42de-896d-aa269c8b673e","type":"text_block","style":{},"content":{"text":"A compliance matrix is a single table with one row for every requirement the solicitation imposes on you, and columns that answer: where is it addressed, who owns it, and is it done. Nothing more clever than that. Its power is that it converts a 60-page solicitation into a finite, checkable list.","inline_formats":[{"start":55,"format":"bold","length":49}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"f2518e5e-9729-4087-ae8b-4bbc455577de","type":"text_block","style":{},"content":{"text":"A row typically records:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"b03b475d-2e43-403f-86bd-f1c201b1dba6","type":"bulleted_list","style":{},"content":{"items":[{"text":"The requirement, quoted, not paraphrased."},{"text":"Where it comes from — the section and page of the solicitation."},{"text":"Where you answer it — your volume, section and page."},{"text":"Owner — one named person."},{"text":"Status — not started, drafted, reviewed, done."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e016095d-f31a-4bcb-8c07-741536d1316f","type":"heading","style":{},"content":{"text":"Finding the requirements","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"62991ac7-7e56-430c-9dae-5390cd88600b","type":"text_block","style":{},"content":{"text":"Read the solicitation with a highlighter and pull every sentence containing:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"ec9da46c-abfe-4b42-892d-d5d99a6630f1","type":"bulleted_list","style":{},"content":{"items":[{"text":"shall, must, is required to, will provide — hard requirements."},{"text":"should, may — softer, but frequently scored anyway."},{"text":"Anything in the instructions to offerors section, which is where format and submission rules hide."},{"text":"Anything in the evaluation criteria, which tells you what reviewers actually score."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"106f1ca0-3c71-415c-afc2-7a619f83bd73","type":"text_block","style":{},"content":{"text":"Two rules that save proposals. First, quote the requirement verbatim — a paraphrase silently drops the qualifier that mattered. Second, split compound requirements: \"the offeror shall describe the approach and provide a schedule and identify key personnel\" is three rows, not one, because it is three ways to be incomplete.","inline_formats":[{"start":60,"format":"bold","length":8},{"start":260,"format":"bold","length":5}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e2592d6d-3b3a-4bde-a2c2-a37ff291f147","type":"heading","style":{},"content":{"text":"Requirements are not only in the narrative","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"7cdf9cad-95f3-4abe-8649-077ce8c1733b","type":"text_block","style":{},"content":{"text":"The rows that get missed are rarely technical. They are the administrative ones: a letter of support, a current SAM registration, a signed certification, a data-management plan, a specific file naming convention, a page-limited summary, a form nobody read past the title of. Every one of those is a row."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"fe3672b1-1f63-4d84-b5d4-f0b1dded1b9d","type":"heading","style":{},"content":{"text":"Working the matrix","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"916b0122-2561-4da7-80d3-c37088b831bd","type":"text_block","style":{},"content":{"text":"Build it before you start writing, not after. Used properly it is the proposal outline — you write to the rows, and the volume structure falls out of it. Review it at every checkpoint: an item that is still unowned two days before the deadline is the item that will be missing.","inline_formats":[{"start":9,"format":"bold","length":6}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"c58ac3bc-1ebb-44b6-8df2-f1fe5ff47991","type":"text_block","style":{},"content":{"text":"The last pass before submission is a straight read of the matrix, row by row, against the assembled document. Not from memory. Against the document."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"64e38344-267b-4f4d-9d79-514b5e90d51e","type":"heading","style":{},"content":{"text":"How this platform helps","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e12ceb0c-5955-4a18-b625-4688f524592b","type":"text_block","style":{},"content":{"text":"The matrix is not something you build by hand here. When an opportunity is curated, the compliance side captures the solicitation's requirements, and a matrix is instantiated with your proposal the moment it is provisioned — every required item already a row, tied to the volume and section that answers it."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"04d86ae9-c788-40bf-88d3-81ef27d17113","type":"text_block","style":{},"content":{"text":"From there it stays current on its own: locking a section advances the items it satisfies, and submission readiness reads the matrix directly, so the verdict on the overview page is the state of your requirements, not somebody's recollection of it. If the agency amends the solicitation, the change is detected, confirmed, and fanned out to every affected build with an acknowledgement — so a requirement that appeared after you started writing does not quietly stay missing."},"history":[],"provenance":{"source":"template"},"library_eligible":false}]}],"layout":{"mode":"flow"}}],"document_id":"9f855a32-61ea-4343-a405-86537467f19d"},"excerpt":"A solicitation can carry two hundred requirements. The matrix is the one artifact that keeps a team from losing one — and it doubles as your proposal outline.","externalUrl":null,"featuredImage":null}$g168b$::jsonb, $g168b$Drafted practice guide — queued for review (#168 wave 3)$g168b$, $g168b$eric@rfppipeline.com$g168b$, now())
