INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('ee21dea1-5cad-4d9a-b918-a72dda71ddf3', $g168b$proposal-compliance-basics$g168b$, 'guide', 1, 'draft', $g168b$Rejected Without Being Read: The Compliance Rules That Do the Damage$g168b$, $g168b$[{"body":"<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">Rejected Without Being Read</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">There are two ways to lose a competition. One is to be outscored, which is a fair fight and tells you something. The other is to be removed before scoring, which teaches you nothing and is entirely avoidable.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The second kind is more common than most first-time applicants expect, and none of it is about the quality of your idea.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The page limit is not a guideline</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Read the sentence in the solicitation carefully, because agencies word it deliberately:</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">&gt; <em>Pages in excess of the stated limit will not be evaluated and will be removed from the proposal prior to evaluation.</em></p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">That is not a threat about a penalty. It is a description of a procedure. Page eleven of a ten-page volume is <em>deleted</em>, and if your conclusion — or your work plan, or your cost summary — was on it, the evaluator reads a proposal that simply stops.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Three things about page limits catch people out:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">What counts. Usually everything: figures, tables, references, appendices. Sometimes the cover sheet and the table of contents are excluded. The solicitation says which, and the two are not interchangeable.</li><li style=\"margin:.25rem 0\">Where the limit lives. The number is often not in the main announcement at all. A DoD BAA will frequently defer it to the Component-specific instructions — a separate document, sometimes attached separately. A page limit you cannot find is not a page limit that does not exist.</li><li style=\"margin:.25rem 0\">The rendered count is the real count. Your word processor's page count and the PDF the agency receives are not always the same document. Check the PDF.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The formatting rules that are actually enforced</h2>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Font size and family. A minimum point size, often 10 or 11, sometimes with a named family. This applies to figure labels and table cells too — shrinking a table to fit is the classic way to fail a rule you thought you had met.</li><li style=\"margin:.25rem 0\">Margins. Typically not less than one inch on all sides. Headers and footers usually sit inside that margin; check whether yours do.</li><li style=\"margin:.25rem 0\">Paper size. 8.5 × 11 in the US. A document laid out on A4 will reflow when it is printed, and your page count will change.</li><li style=\"margin:.25rem 0\">File format and naming. Some portals reject a file whose name has a space or a special character in it. Some require PDF/A. Some cap the file size.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The deadline is a timestamp, not a day</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Submission deadlines are stated to the minute and in a specific time zone — often Eastern, sometimes the agency's local time. Portals close on that timestamp. A proposal uploading at the moment of the cutoff is a proposal that did not arrive.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The practical rule that experienced teams follow: <strong>submit a complete, compliant version at least a day early</strong>, then replace it if you improve it. Most portals let you overwrite a submission until the deadline. What you cannot do is start uploading at the deadline and hope.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Registrations expire</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Federal submission requires an active <strong>SAM.gov</strong> registration, and for SBIR/STTR an SBC number from <strong>SBIR.gov</strong>. SAM registration must be renewed annually, and renewal is not instant — it can take days or weeks if anything needs validating. A lapsed registration discovered in the final week is how a good proposal misses a cycle entirely.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Check the expiry date the day you decide to bid, not the week you submit.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How to check yourself</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Before you submit, walk the solicitation's instructions section line by line and mark each rule against your actual file. Not your intent — your file. The four questions worth asking out loud:</p>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">What does the PDF's page count say, on the volume as it will be received?</li><li style=\"margin:.25rem 0\">Does every rule in the instructions have a place I can point to where I meet it?</li><li style=\"margin:.25rem 0\">Is every required item present, including the ones with no page count — letters, forms, certifications?</li><li style=\"margin:.25rem 0\">Is the submission portal open, and is my registration current today?</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The compliance rules for a solicitation are read into a <strong>matrix</strong> during ingest, and each value carries its provenance: read from the source with a citation, or flagged as an unverified default. A page limit the solicitation defers elsewhere is shown as <em>set elsewhere</em> with the citation — never as a made-up number, which is the one thing worse than not knowing.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Page limits are then enforced against the <strong>rendered</strong> document rather than an estimate: the export is laid out by a real browser and counted, so what is checked is the file you would submit. Font, margin and per-section limits are checked in the same pass, and a volume over its cap is refused at the export gate rather than discovered by an evaluator.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">None of that replaces reading the solicitation. It means the reading has somewhere to land.</p>","title":"Rejected Without Being Read: The Compliance Rules That Do the Damage","excerpt":"Page limits, fonts, margins, file formats and deadlines — the mechanical rules that get proposals removed before an evaluator ever sees them, and how to check yourself.","section":"body","metadata":{}}]$g168b$::jsonb, $g168b${"tags":["compliance","page-limits","submission","getting-started"],"author":null,"canvas":{"nodes":[],"canvas":{"width":612,"footer":null,"format":"custom","header":null,"height":792,"margins":{"top":72,"left":72,"right":72,"bottom":72},"max_pages":null,"max_slides":null,"font_default":{"size":12,"family":"Times New Roman"},"line_spacing":1.15},"version":2,"metadata":{"title":"Rejected Without Being Read: The Compliance Rules That Do the Damage","status":"in_progress","volume_id":"","created_at":"","proposal_id":"","version_number":1,"solicitation_id":"","last_modified_at":"","last_modified_by":"","required_item_id":""},"sections":[{"id":"66e7e1d2-71a0-4a87-9e36-6c8cfc02f082","title":"Rejected Without Being Read: The Compliance Rules That Do the Damage","groups":[{"id":"ea43709d-aa68-4fb9-bb61-a558ac62cb3a","nodes":[{"id":"f9a5da24-f427-45f1-8b97-f0f77850bf5f","type":"heading","style":{},"content":{"text":"Rejected Without Being Read","level":1},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"18333b6d-c0c5-4636-8460-09e6f26637e3","type":"text_block","style":{},"content":{"text":"There are two ways to lose a competition. One is to be outscored, which is a fair fight and tells you something. The other is to be removed before scoring, which teaches you nothing and is entirely avoidable."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"02a62622-fb32-47ba-b666-f2fda4cca5e7","type":"text_block","style":{},"content":{"text":"The second kind is more common than most first-time applicants expect, and none of it is about the quality of your idea."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"31f947a0-d9fc-4659-aafe-d206e364f64f","type":"heading","style":{},"content":{"text":"The page limit is not a guideline","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"15d5643a-80ba-44df-97ee-6554b83a0c4a","type":"text_block","style":{},"content":{"text":"Read the sentence in the solicitation carefully, because agencies word it deliberately:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"143fda5b-e3ec-44ef-9578-367c36491767","type":"text_block","style":{},"content":{"text":"> Pages in excess of the stated limit will not be evaluated and will be removed from the proposal prior to evaluation.","inline_formats":[{"start":2,"format":"italic","length":116}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"44a7a704-f5c6-4e02-923c-0e5b98a1d6a1","type":"text_block","style":{},"content":{"text":"That is not a threat about a penalty. It is a description of a procedure. Page eleven of a ten-page volume is deleted, and if your conclusion — or your work plan, or your cost summary — was on it, the evaluator reads a proposal that simply stops.","inline_formats":[{"start":110,"format":"italic","length":7}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"2e3b7ad8-faed-4967-863e-e1840437a972","type":"text_block","style":{},"content":{"text":"Three things about page limits catch people out:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"6ee5cbec-6480-4943-97b7-b8440dafda04","type":"bulleted_list","style":{},"content":{"items":[{"text":"What counts. Usually everything: figures, tables, references, appendices. Sometimes the cover sheet and the table of contents are excluded. The solicitation says which, and the two are not interchangeable."},{"text":"Where the limit lives. The number is often not in the main announcement at all. A DoD BAA will frequently defer it to the Component-specific instructions — a separate document, sometimes attached separately. A page limit you cannot find is not a page limit that does not exist."},{"text":"The rendered count is the real count. Your word processor's page count and the PDF the agency receives are not always the same document. Check the PDF."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"876c6688-3ec8-4017-9203-ffc590c6688c","type":"heading","style":{},"content":{"text":"The formatting rules that are actually enforced","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"f0fb85fd-993b-4872-a920-25d7a75c589c","type":"bulleted_list","style":{},"content":{"items":[{"text":"Font size and family. A minimum point size, often 10 or 11, sometimes with a named family. This applies to figure labels and table cells too — shrinking a table to fit is the classic way to fail a rule you thought you had met."},{"text":"Margins. Typically not less than one inch on all sides. Headers and footers usually sit inside that margin; check whether yours do."},{"text":"Paper size. 8.5 × 11 in the US. A document laid out on A4 will reflow when it is printed, and your page count will change."},{"text":"File format and naming. Some portals reject a file whose name has a space or a special character in it. Some require PDF/A. Some cap the file size."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"bb77b172-9a52-4ddd-b87a-7fdea013fd5a","type":"heading","style":{},"content":{"text":"The deadline is a timestamp, not a day","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"1f0e4678-0143-4686-ade0-170065d32345","type":"text_block","style":{},"content":{"text":"Submission deadlines are stated to the minute and in a specific time zone — often Eastern, sometimes the agency's local time. Portals close on that timestamp. A proposal uploading at the moment of the cutoff is a proposal that did not arrive."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e1c0786f-635d-4520-a86b-a80d6037658a","type":"text_block","style":{},"content":{"text":"The practical rule that experienced teams follow: submit a complete, compliant version at least a day early, then replace it if you improve it. Most portals let you overwrite a submission until the deadline. What you cannot do is start uploading at the deadline and hope.","inline_formats":[{"start":50,"format":"bold","length":57}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"549cc354-a2bb-4a0d-b0fc-b8e881011d57","type":"heading","style":{},"content":{"text":"Registrations expire","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"fc72c5ef-5fe1-4aac-badf-c975eeb46b41","type":"text_block","style":{},"content":{"text":"Federal submission requires an active SAM.gov registration, and for SBIR/STTR an SBC number from SBIR.gov. SAM registration must be renewed annually, and renewal is not instant — it can take days or weeks if anything needs validating. A lapsed registration discovered in the final week is how a good proposal misses a cycle entirely.","inline_formats":[{"start":38,"format":"bold","length":7},{"start":97,"format":"bold","length":8}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"18717fe0-c5ee-4851-85b6-aef41f7482f1","type":"text_block","style":{},"content":{"text":"Check the expiry date the day you decide to bid, not the week you submit."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"cbc81b30-70fc-4a4e-99ff-998d210b50d5","type":"heading","style":{},"content":{"text":"How to check yourself","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"8d1fe9d2-b312-4cac-a62e-9077303ba466","type":"text_block","style":{},"content":{"text":"Before you submit, walk the solicitation's instructions section line by line and mark each rule against your actual file. Not your intent — your file. The four questions worth asking out loud:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e74c3dab-81ea-4db2-bd72-b7e054f56fc9","type":"numbered_list","style":{},"content":{"items":[{"text":"What does the PDF's page count say, on the volume as it will be received?"},{"text":"Does every rule in the instructions have a place I can point to where I meet it?"},{"text":"Is every required item present, including the ones with no page count — letters, forms, certifications?"},{"text":"Is the submission portal open, and is my registration current today?"}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"5749174a-ce90-4d8e-ae23-6768d1f86870","type":"heading","style":{},"content":{"text":"How this platform helps","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"5ca53b04-434f-447e-94d4-a7c0a90f0c04","type":"text_block","style":{},"content":{"text":"The compliance rules for a solicitation are read into a matrix during ingest, and each value carries its provenance: read from the source with a citation, or flagged as an unverified default. A page limit the solicitation defers elsewhere is shown as set elsewhere with the citation — never as a made-up number, which is the one thing worse than not knowing.","inline_formats":[{"start":56,"format":"bold","length":6},{"start":251,"format":"italic","length":13}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"de2394aa-f5d7-4da7-9b2a-c19607c4c97f","type":"text_block","style":{},"content":{"text":"Page limits are then enforced against the rendered document rather than an estimate: the export is laid out by a real browser and counted, so what is checked is the file you would submit. Font, margin and per-section limits are checked in the same pass, and a volume over its cap is refused at the export gate rather than discovered by an evaluator.","inline_formats":[{"start":42,"format":"bold","length":8}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"7ced0b10-5a7a-47c4-b4d2-6ff0cce1e8f1","type":"text_block","style":{},"content":{"text":"None of that replaces reading the solicitation. It means the reading has somewhere to land."},"history":[],"provenance":{"source":"template"},"library_eligible":false}]}],"layout":{"mode":"flow"}}],"document_id":"3d4e4560-02ca-4010-ad8e-9b38487150c3"},"excerpt":"Page limits, fonts, margins, file formats and deadlines — the mechanical rules that get proposals removed before an evaluator ever sees them, and how to check yourself.","externalUrl":null,"featuredImage":null}$g168b$::jsonb, $g168b$Drafted follow-on guide — queued for review (#168)$g168b$, $g168b$eric@rfppipeline.com$g168b$, now())
ON CONFLICT (id) DO NOTHING;

INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('1b9e521c-69b5-4255-afa0-f0156e4ab329', $g168b$registrations-before-you-bid$g168b$, 'guide', 1, 'draft', $g168b$Registrations to Get Done Before You Bid$g168b$, $g168b$[{"body":"<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">Registrations to Get Done Before You Bid</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The single most avoidable way to lose a federal opportunity is to find a good one, write a strong proposal, and then discover you cannot submit it because a registration is incomplete. These are administrative steps with <strong>government processing times attached</strong>. You cannot compress them by working harder the night before.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Start them now, before you have a deadline. They are good for years once done.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The ones nearly everyone needs</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\"><strong>SAM.gov registration.</strong> The System for Award Management is the government-wide registry of entities eligible to receive federal awards. Registering assigns your <strong>UEI (Unique Entity Identifier)</strong> — the number that replaced DUNS — and generally your <strong>CAGE code</strong> as well. You will need your legal entity name exactly as the IRS has it, your EIN, and banking details for electronic payment. Access goes through a Login.gov account with identity verification.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\">This is the one to start first. Validation of your legal business name and address is where registrations stall, and it is resolved by the government on its schedule, not yours. Renewal is annual — an <strong>expired SAM registration blocks submission just as effectively as never having one</strong>, and it expires quietly.</p>\n<p style=\"margin:0 0 1rem;line-height:1.7\"><strong>The SBIR/STTR company registry.</strong> SBIR.gov maintains a separate registration for small business concerns, which issues an SBC Control ID that agency proposal systems ask for. Doing your SAM registration does not do this one.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Agency portals, on top of the above</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Each agency runs its own submission system, and each needs its own account:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">DoD/DoW — the Defense SBIR/STTR Innovation Portal (DSIP), used across the services.</li><li style=\"margin:.25rem 0\">NSF — Research.gov.</li><li style=\"margin:.25rem 0\">NIH — eRA Commons, plus Grants.gov.</li><li style=\"margin:.25rem 0\">Grant-based programs generally — Grants.gov, where an authorised organisational representative has to be designated before anyone can submit on the company's behalf.</li></ul>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Two things to know. First, several of these require a person to be <em>authorised by the organisation</em>, which is its own approval step with its own delay. Second, portal accounts are tied to individuals — if the only person with submission rights leaves, or is on a plane on deadline day, that is a problem you solve in advance or not at all.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Eligibility facts worth confirming early</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Registration proves you exist. It does not prove you qualify. Confirm separately that your company meets the ownership and size requirements for the program, that your principal investigator meets the employment rule the program imposes, and that the work will be performed where the program requires. Finding out otherwise after you have written a proposal is expensive; the eligibility checklist guide covers this in more detail.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">A working sequence</h2>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Login.gov, with identity verification completed.</li><li style=\"margin:.25rem 0\">SAM.gov registration — start here, and expect entity validation to take real time.</li><li style=\"margin:.25rem 0\">SBIR.gov company registry, once you have your UEI.</li><li style=\"margin:.25rem 0\">Agency portal accounts for the agencies you actually intend to bid, with more than one authorised person where the portal allows it.</li><li style=\"margin:.25rem 0\">Calendar the SAM renewal a month before it lapses, every year.</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Nothing on this list is something software can do for you — these are your company's credentials, held by your company. What the platform does is make sure they are not what you are thinking about on deadline day: registration items appear as required rows in your compliance matrix, with an owner and a due date on the workflow, so they are tracked the same way as the rest of the submission rather than remembered. The published resources list links straight to SAM.gov, SBIR.gov, DSIP and Grants.gov.</p>","title":"Registrations to Get Done Before You Bid","excerpt":"SAM, your UEI, the SBIR company registry, agency portals — the accounts that gate submission, and why starting them the week of a deadline is too late.","section":"body","metadata":{}}]$g168b$::jsonb, $g168b${"tags":["SAM.gov","UEI","registration","getting started"],"author":null,"canvas":{"nodes":[],"canvas":{"width":612,"footer":null,"format":"custom","header":null,"height":792,"margins":{"top":72,"left":72,"right":72,"bottom":72},"max_pages":null,"max_slides":null,"font_default":{"size":12,"family":"Times New Roman"},"line_spacing":1.15},"version":2,"metadata":{"title":"Registrations to Get Done Before You Bid","status":"in_progress","volume_id":"","created_at":"","proposal_id":"","version_number":1,"solicitation_id":"","last_modified_at":"","last_modified_by":"","required_item_id":""},"sections":[{"id":"dfc00b6f-16cd-4957-b156-4e883670c4f7","title":"Registrations to Get Done Before You Bid","groups":[{"id":"a651c140-120c-4c84-a8ae-8022083508e9","nodes":[{"id":"1950dbfe-5e04-4252-bb22-b06cf8882c6b","type":"heading","style":{},"content":{"text":"Registrations to Get Done Before You Bid","level":1},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"101e7c33-8c59-48c8-b07a-b33eca4fff71","type":"text_block","style":{},"content":{"text":"The single most avoidable way to lose a federal opportunity is to find a good one, write a strong proposal, and then discover you cannot submit it because a registration is incomplete. These are administrative steps with government processing times attached. You cannot compress them by working harder the night before.","inline_formats":[{"start":221,"format":"bold","length":36}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"b6869ae4-1514-4851-bddd-741465a474ec","type":"text_block","style":{},"content":{"text":"Start them now, before you have a deadline. They are good for years once done."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"3806401e-6eb2-4476-946f-732a52193c84","type":"heading","style":{},"content":{"text":"The ones nearly everyone needs","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"c1012000-a9ee-422f-ae07-0f39439c9903","type":"text_block","style":{},"content":{"text":"SAM.gov registration. The System for Award Management is the government-wide registry of entities eligible to receive federal awards. Registering assigns your UEI (Unique Entity Identifier) — the number that replaced DUNS — and generally your CAGE code as well. You will need your legal entity name exactly as the IRS has it, your EIN, and banking details for electronic payment. Access goes through a Login.gov account with identity verification.","inline_formats":[{"start":0,"format":"bold","length":21},{"start":159,"format":"bold","length":30},{"start":243,"format":"bold","length":9}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"bef1a65d-075f-4f7c-ba48-d1711c710e9a","type":"text_block","style":{},"content":{"text":"This is the one to start first. Validation of your legal business name and address is where registrations stall, and it is resolved by the government on its schedule, not yours. Renewal is annual — an expired SAM registration blocks submission just as effectively as never having one, and it expires quietly.","inline_formats":[{"start":201,"format":"bold","length":82}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e1862823-dc5b-425d-9979-48788132ada4","type":"text_block","style":{},"content":{"text":"The SBIR/STTR company registry. SBIR.gov maintains a separate registration for small business concerns, which issues an SBC Control ID that agency proposal systems ask for. Doing your SAM registration does not do this one.","inline_formats":[{"start":0,"format":"bold","length":31}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"5c956e94-580e-4960-b24e-2c5c9fdad91b","type":"heading","style":{},"content":{"text":"Agency portals, on top of the above","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"66d2e656-e7b0-478e-9c94-f33bdec627ce","type":"text_block","style":{},"content":{"text":"Each agency runs its own submission system, and each needs its own account:"},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"bf4ceda1-d47f-454c-8bf0-6e98d2bb57c3","type":"bulleted_list","style":{},"content":{"items":[{"text":"DoD/DoW — the Defense SBIR/STTR Innovation Portal (DSIP), used across the services."},{"text":"NSF — Research.gov."},{"text":"NIH — eRA Commons, plus Grants.gov."},{"text":"Grant-based programs generally — Grants.gov, where an authorised organisational representative has to be designated before anyone can submit on the company's behalf."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"f06e0bc3-f104-499d-a6dc-be739db923b9","type":"text_block","style":{},"content":{"text":"Two things to know. First, several of these require a person to be authorised by the organisation, which is its own approval step with its own delay. Second, portal accounts are tied to individuals — if the only person with submission rights leaves, or is on a plane on deadline day, that is a problem you solve in advance or not at all.","inline_formats":[{"start":67,"format":"italic","length":30}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"d6389c89-7184-44ae-af95-2f84fc762f3f","type":"heading","style":{},"content":{"text":"Eligibility facts worth confirming early","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"709a937e-8d62-48df-acd2-3e776d189b24","type":"text_block","style":{},"content":{"text":"Registration proves you exist. It does not prove you qualify. Confirm separately that your company meets the ownership and size requirements for the program, that your principal investigator meets the employment rule the program imposes, and that the work will be performed where the program requires. Finding out otherwise after you have written a proposal is expensive; the eligibility checklist guide covers this in more detail."},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"b7472530-768e-4df2-9a84-96caa68d16de","type":"heading","style":{},"content":{"text":"A working sequence","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"33e27333-ca0e-49d0-89b0-ceafe1e81a87","type":"numbered_list","style":{},"content":{"items":[{"text":"Login.gov, with identity verification completed."},{"text":"SAM.gov registration — start here, and expect entity validation to take real time."},{"text":"SBIR.gov company registry, once you have your UEI."},{"text":"Agency portal accounts for the agencies you actually intend to bid, with more than one authorised person where the portal allows it."},{"text":"Calendar the SAM renewal a month before it lapses, every year."}]},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"e3921c4b-3ee5-4453-92fb-bcd833393e47","type":"heading","style":{},"content":{"text":"How this platform helps","level":2},"history":[],"provenance":{"source":"template"},"library_eligible":false},{"id":"ece722ff-4a2c-440d-b358-fdbb1275ed5e","type":"text_block","style":{},"content":{"text":"Nothing on this list is something software can do for you — these are your company's credentials, held by your company. What the platform does is make sure they are not what you are thinking about on deadline day: registration items appear as required rows in your compliance matrix, with an owner and a due date on the workflow, so they are tracked the same way as the rest of the submission rather than remembered. The published resources list links straight to SAM.gov, SBIR.gov, DSIP and Grants.gov."},"history":[],"provenance":{"source":"template"},"library_eligible":false}]}],"layout":{"mode":"flow"}}],"document_id":"48a2420d-cd9b-4e6f-81a8-4aaae529d281"},"excerpt":"SAM, your UEI, the SBIR company registry, agency portals — the accounts that gate submission, and why starting them the week of a deadline is too late.","externalUrl":null,"featuredImage":null}$g168b$::jsonb, $g168b$Drafted practice guide — queued for review (#168 wave 3)$g168b$, $g168b$eric@rfppipeline.com$g168b$, now())
